using System.Collections.Generic;
using System.IO;
using UnityEngine;

namespace ArenaMode.Hud.InfoPanels.UI
{
    // Purpose-built sprites, generated by the scripts under tools\ and embedded
    // into the DLL. The EFT item sprites are too detailed to stay readable at
    // HUD size, so these are designed for that size specifically.
    internal static class EmbeddedIcons
    {
        // Nulls are cached too so a missing resource logs once instead of
        // retrying (and re-warning) on every refresh tick.
        private static readonly Dictionary<string, Sprite> _cache = new Dictionary<string, Sprite>();

        internal static void Reset()
        {
            foreach (var sprite in _cache.Values)
            {
                try
                {
                    if (sprite == null) continue;
                    var texture = sprite.texture;
                    Object.Destroy(sprite);
                    if (texture != null) Object.Destroy(texture);
                }
                catch (System.Exception ex) { ArenaMode.Plugin.ModLogger.LogWarning($"Arena panel icon cleanup failed: {ex.Message}"); }
            }
            _cache.Clear();
        }

        public static Sprite MagFull => Get("mag_full.png");
        public static Sprite MagPartial => Get("mag_partial.png");

        public static Sprite Get(string fileName)
        {
            if (_cache.TryGetValue(fileName, out Sprite sprite))
            {
                return sprite;
            }

            sprite = LoadSprite(fileName, 0f);
            _cache[fileName] = sprite;
            return sprite;
        }

        // 9-sliced variant: the border keeps the rounded corners at their drawn
        // size while the middle stretches, so one 64x64 sprite fits every panel.
        public static Sprite GetSliced(string fileName, float border)
        {
            string key = fileName + "#" + border;
            if (_cache.TryGetValue(key, out Sprite sprite))
            {
                return sprite;
            }

            sprite = LoadSprite(fileName, border);
            _cache[key] = sprite;
            return sprite;
        }

        private static Sprite LoadSprite(string fileName, float border)
        {
            using (Stream stream = typeof(EmbeddedIcons).Assembly
                       .GetManifestResourceStream("ArenaMode.Hud.InfoPanels.Icons." + fileName))
            {
                if (stream == null)
                {
                    ArenaMode.Plugin.ModLogger?.LogWarning($"Embedded icon missing: {fileName}");
                    return null;
                }

                var data = new byte[stream.Length];
                int offset = 0;
                while (offset < data.Length)
                {
                    int read = stream.Read(data, offset, data.Length - offset);
                    if (read <= 0)
                    {
                        break;
                    }

                    offset += read;
                }

                var texture = new Texture2D(2, 2, TextureFormat.RGBA32, false);
                if (!texture.LoadImage(data))
                {
                    ArenaMode.Plugin.ModLogger?.LogWarning($"Embedded icon failed to decode: {fileName}");
                    Object.Destroy(texture);
                    return null;
                }

                texture.filterMode = FilterMode.Bilinear;
                texture.wrapMode = TextureWrapMode.Clamp;

                var rect = new Rect(0f, 0f, texture.width, texture.height);
                var pivot = new Vector2(0.5f, 0.5f);
                if (border <= 0f)
                {
                    return Sprite.Create(texture, rect, pivot);
                }

                // FullRect is required for 9-slicing to work at all.
                return Sprite.Create(
                    texture,
                    rect,
                    pivot,
                    100f,
                    0,
                    SpriteMeshType.FullRect,
                    new Vector4(border, border, border, border));
            }
        }
    }
}
